package SmartMicrogrid {
  import sysml;

  actor FacilityManager;
  actor MaintenanceTechnician;
  actor UtilityGridOperator;
  actor WeatherService;
  actor EVDriver;

  block MicrogridController {
    attribute mode: string;
    attribute dispatchIntervalMs: int;
    attribute islandTimeoutMs: int;
    part meter: Block;
    part pv: Block;
    part battery: Block;
    part inverter: Block;
    part loadMgr: Block;
    part forecaster: Block;
    part comms: Block;
    part logger: Block;
    part cyber: Block;
  }

  block PowerMeter {
    attribute siteKW: float;
    attribute siteKVAR: float;
    attribute timestamp: string;
  }

  block PVArray {
    attribute maxKW: float;
    attribute currentKW: float;
    attribute irradianceWm2: float;
  }

  block BatteryPack {
    attribute socPct: float;
    attribute maxChargeKW: float;
    attribute maxDischargeKW: float;
    part bms: Block;
  }

  block BMS {
    attribute packVoltageV: float;
    attribute packCurrentA: float;
    attribute tempC: float;
  }

  block Inverter {
    attribute acSetpointKW: float;
    attribute status: string;
    attribute efficiencyPct: float;
  }

  block LoadManager {
    attribute criticalKW: float;
    attribute nonCriticalKW: float;
    attribute shedState: string;
    part criticalLoads: Block;
    part nonCriticalLoads: Block;
  }

  block LoadGroup {
    attribute name: string;
    attribute commandedState: string;
    attribute demandKW: float;
  }

  block ForecastEngine {
    attribute horizonHours: int;
    attribute intervalMin: int;
    attribute forecastQuality: string;
  }

  usecase MonitorPowerFlows {
    subject MicrogridController;
    actor FacilityManager;
  }

  usecase StartUpSelfTest {
    subject MicrogridController;
    actor MaintenanceTechnician;
  }

  usecase OptimizeDispatch {
    subject MicrogridController;
    actor FacilityManager;
    actor WeatherService;
  }

  usecase EnterIslandMode {
    subject MicrogridController;
    actor UtilityGridOperator;
  }

  usecase RestoreGridConnection {
    subject MicrogridController;
    actor UtilityGridOperator;
    actor FacilityManager;
  }

  usecase ShedNonCriticalLoads {
    subject LoadManager;
    actor FacilityManager;
  }

  usecase ScheduleEVCharging {
    subject MicrogridController;
    actor EVDriver;
    actor FacilityManager;
  }

  usecase ViewAuditLog {
    subject AuditLogger;
    actor MaintenanceTechnician;
    actor FacilityManager;
  }

  usecase RespondToDeviceCommFault {
    subject CommsGateway;
    actor MaintenanceTechnician;
  }

  requirement R-001 "The system shall update power dispatch commands at least every 1 second.";
  requirement R-002 "The system shall maintain critical-load power during grid loss by entering island mode within 200 ms.";
  requirement R-003 "The system shall limit battery charge/discharge current to configured maximums to prevent overcurrent events.";
  requirement R-004 "The system shall prioritize critical loads over non-critical loads during capacity shortfalls.";
  requirement R-005 "The system shall forecast site load and PV generation at 15-minute resolution for at least the next 24 hours.";
  requirement R-006 "The system shall log all dispatch decisions with timestamp, inputs used, and resulting setpoints for audit purposes.";
  requirement R-007 "The system shall provide an operator dashboard that shows real-time power flows and device status within 2 seconds of measurement.";

}
